package com.hmdp.upgrade;

import com.hmdp.upgrade.assistant.*;
import com.hmdp.upgrade.assistant.AssistantData.*;
import java.nio.file.Path;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.core.io.ClassPathResource;
import org.springframework.jdbc.datasource.init.ResourceDatabasePopulator;
import org.springframework.test.util.ReflectionTestUtils;
import static org.junit.jupiter.api.Assertions.*;

class LocalPersonalisationTest {
    @TempDir Path files;LocalLifeTest f;LocalPreferences preferences;
    @BeforeEach void setup(){f=new LocalLifeTest();f.files=files;f.setup();new ResourceDatabasePopulator(new ClassPathResource("db/migration/V19__local_preferences.sql")).execute(f.db.getDataSource());preferences=new LocalPreferences(f.db,f.tx,f.json,f.config);ReflectionTestUtils.setField(f.agent,"preferences",preferences);ReflectionTestUtils.setField(f.shops,"preferences",preferences);}
    Object save(long user,Map<String,Object> values,int version){return preferences.save(user,Map.of("values",values,"enabled",true,"version",version));}
    @Test void explicitPreferencesPersistPerOwnerAndRejectStaleOverwrites(){save(1,Map.of("campus","主校区","maxPriceCents",3500,"preferredTags",List.of("安静")),0);assertEquals("主校区",preferences.values(1).get("campus"));assertTrue(preferences.values(2).isEmpty());assertThrows(Problem.class,()->save(1,Map.of("campus","东校区"),0));assertEquals("主校区",preferences.values(1).get("campus"));}
    @Test void defaultsApplyAtStartExplicitChangesWinAndResetDoesNotReapply(){save(1,Map.of("maxPriceCents",2000,"campus","主校区"),0);var cp=new Checkpoint();assertTrue(f.agent.execute("search_shops",f.json.createObjectNode(),1,cp).path("data").path("shops").isEmpty());var next=new Checkpoint();next.state=cp.state;assertEquals(1,f.agent.execute("search_shops",f.json.createObjectNode().put("maxPriceCents",4000),1,next).path("data").path("shops").size());var reset=new Checkpoint();reset.state=next.state;f.agent.execute("search_shops",f.json.createObjectNode().put("reset",true),1,reset);assertFalse(reset.state.shopFilters.containsKey("maxPriceCents"));assertFalse(reset.state.shopFilters.containsKey("campus"));assertTrue(reset.state.shopDefaultsApplied);}
    @Test void preferenceProposalIsNotAWriteAndOnlyContainsValidatedFields(){var cp=new Checkpoint();var draft=f.agent.execute("prepare_preferences",f.json.createObjectNode().set("values",f.json.valueToTree(Map.of("preferredTags",List.of("安静")))),1,cp);assertEquals("PREFERENCE_DRAFT",draft.path("kind").asText());assertTrue(preferences.values(1).isEmpty());assertThrows(Problem.class,()->f.agent.execute("prepare_preferences",f.json.createObjectNode().set("values",f.json.valueToTree(Map.of("userId",2))),1,new Checkpoint()));assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM ux_life_preference",Integer.class));}
    @Test void disablingAndClearingPreferencesStopDefaultFilters(){save(1,Map.of("maxPriceCents",2000),0);preferences.save(1,Map.of("enabled",false,"version",1,"values",Map.of("maxPriceCents",2000)));assertTrue(preferences.defaults(1).isEmpty());assertEquals(1,f.agent.execute("search_shops",f.json.createObjectNode(),1,new Checkpoint()).path("data").path("shops").size());preferences.clear(1);assertEquals(0,preferences.read(1).get("version"));}
    @Test void exclusionsUseExactKnownTagsAndCanBeExplicitlyCleared(){save(1,Map.of("avoidedTags",List.of("安静")),0);var cp=new Checkpoint();assertTrue(f.agent.execute("search_shops",f.json.createObjectNode(),1,cp).path("data").path("shops").isEmpty());var next=new Checkpoint();next.state=cp.state;assertEquals(1,f.agent.execute("search_shops",f.json.createObjectNode().putNull("avoidedTags"),1,next).path("data").path("shops").size());}
    @Test void totalBudgetQuestionRetainsAmountUntilChinesePartySizeReply()throws Exception{var cp=new Checkpoint();var model=new DemoAssistantModel(f.json);cp.localEnabled=true;var call=model.next(cp,"一共60元，推荐咖啡店",Instant.now(),1000).message().path("tool_calls").get(0).path("function");assertThrows(Problem.class,()->f.agent.execute(call.path("name").asText(),f.json.readTree(call.path("arguments").asText()),1,cp));assertEquals("6000",cp.state.shopFilters.get("totalBudgetCents"));var next=new Checkpoint();next.state=cp.state;next.localEnabled=true;var reply=model.next(next,"两个人",Instant.now(),1000).message().path("tool_calls").get(0).path("function");assertEquals("search_shops",reply.path("name").asText());f.agent.execute("search_shops",f.json.readTree(reply.path("arguments").asText()),1,next);assertEquals("3000",next.state.shopFilters.get("maxPriceCents"));}
    @Test void recommendationReasonsAreDerivedFromRealFilters(){var cp=new Checkpoint();var r=f.agent.execute("search_shops",f.json.createObjectNode().put("campus","主校区").put("maxPriceCents",4000),1,cp);assertTrue(r.path("data").path("shops").get(0).path("recommendationReasons").toString().contains("符合预算"));assertFalse(r.toString().contains("保证有座"));}
    @Test void preferenceRankingDoesNotLeakAnotherAccountsChoices(){f.db.update("INSERT INTO ux_shop VALUES(2,'普通小馆','一间校园食堂测试资料，提供普通家常餐。',1)");f.db.update("INSERT INTO ux_local_shop(shop_id,category,campus,area,address,avg_price_cents,hours_json,closed_dates_json,tags_json,photos_json,cover_path,status,priority,updated_at) VALUES(2,'美食','主校区','大学路','校园',3000,'[]','[]','[]','[]','/local-assets/shop-1.svg','PUBLISHED',0,CURRENT_TIMESTAMP)");save(1,Map.of("preferredCategories",List.of("美食")),0);var own=f.json.valueToTree(f.shops.list(Map.of(),1L));var other=f.json.valueToTree(f.shops.list(Map.of(),2L));assertEquals("2",own.path("items").get(0).path("id").asText());assertEquals("1",other.path("items").get(0).path("id").asText());}
    @Test void policyKeywordRankingFindsActualAnswerBeforeGenericCategory(){for(String[] item:List.of(new String[]{"优惠券可以叠加吗","叠加","优惠券不能叠加，活动门票也不使用此优惠券。"},new String[]{"优惠券过期怎么办","过期","优惠券到达截止时间后不可核销，不能继续使用。"}))f.ops.savePolicy(3,null,Map.of("title",item[0],"keywords",item[1],"body",item[2],"category","券","state","PUBLISHED"));assertEquals("优惠券过期怎么办",f.ops.policies("我的优惠券过期怎么办").get(0).get("title"));}
    @Test void modelToolSchemasCoverMemoryWithoutAllowingAnIdentityArgument(){var schemas=DeepSeekAssistantModel.schemas(f.json,true);assertTrue(schemas.stream().anyMatch(x->f.json.valueToTree(x).path("function").path("name").asText().equals("prepare_preferences")));for(String name:LocalAssistantTools.NAMES)assertThrows(Problem.class,()->f.agent.execute(name,f.json.createObjectNode().put("userId",2),1,new Checkpoint()));}
    @Test void photoMigrationPreservesUserUploadsAndUsesRealBundledImages(){f.db.update("UPDATE ux_local_shop SET shop_id=shop_id WHERE shop_id=1");new ResourceDatabasePopulator(new ClassPathResource("db/migration/V20__local_photography.sql")).execute(f.db.getDataSource());assertEquals("/local-assets/shop-1.svg",f.db.queryForObject("SELECT cover_path FROM ux_local_shop WHERE shop_id=1",String.class));assertTrue(LocalPhotoCatalog.cover(32001).startsWith("/local-photos/"));assertEquals(3,LocalPhotoCatalog.photos(32001).size());}
    @Test void invalidPreferenceTypesNeverReachTheDatabase(){for(Map<String,Object> bad:List.<Map<String,Object>>of(Map.of("maxPriceCents",-1),Map.of("campus","火星"),Map.of("preferredTags","安静"),Map.of("excludedCategories",List.of("所有店")),Map.of("unknown","secret")))assertThrows(Problem.class,()->save(1,bad,0));assertTrue(preferences.values(1).isEmpty());}
    @Test void customerServiceKeepsCouponFactsAlongsidePublishedExplanationWithoutCodes(){var coupon=f.coupon(1,f.template(1));f.ops.savePolicy(3,null,Map.of("title","优惠券使用规则","category","券","keywords","过期","body","达到截止时间后，优惠券不可继续使用。","state","PUBLISHED"));var cp=new Checkpoint();f.agent.execute("get_my_coupons",f.json.createObjectNode(),1,cp);f.agent.execute("search_policies",f.json.createObjectNode().put("q","优惠券过期"),1,cp);var reply=AssistantReplies.render(cp,Instant.now());assertEquals("POLICIES",reply.local().path("kind").asText());assertEquals("MY_COUPONS",reply.local().path("supporting").get(0).path("kind").asText());assertFalse(reply.local().toString().contains(coupon.get("redeemCode").toString()));}
}
